def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False

    def can(i, s):             # can the first i numbers make s?
        if s == 0:
            return True
        if i == 0:
            return False
        if nums[i - 1] <= s and can(i - 1, s - nums[i - 1]):
            return True
        return can(i - 1, s)
    return can(len(nums), total // 2)

