def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    half, n = total // 2, len(nums)
    dp = [[False] * (half + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True
    for i in range(1, n + 1):
        x = nums[i - 1]
        for s in range(1, half + 1):
            dp[i][s] = dp[i - 1][s] or (x <= s and dp[i - 1][s - x])
    return dp[n][half]

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    half = total // 2
    prev = [True] + [False] * half
    for x in nums:
        cur = prev[:]
        for s in range(x, half + 1):
            cur[s] = prev[s] or prev[s - x]
        prev = cur
    return prev[half]

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    half = total // 2
    can = [True] + [False] * half
    for x in nums:
        for s in range(half, x - 1, -1):
            if can[s - x]:
                can[s] = True
        if can[half]:
            return True
    return can[half]

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    bits = 1                   # only sum 0 reachable
    for x in nums:
        bits |= bits << x
    return bool(bits >> (total // 2) & 1)
